package com.opensocket.aievent.core.issuetracking.application.change;
import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.time.*; import java.util.*; import java.util.HexFormat; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
import com.opensocket.aievent.core.integration.identity.IntegrationRiskLevel; import com.opensocket.aievent.core.issuetracking.change.*; import com.opensocket.aievent.core.issuetracking.core.ProviderActionCandidateStateMachine; import com.opensocket.aievent.core.issuetracking.identity.ProviderExecutionAuthorizationRef;
@Service public class ProviderActionCandidateService {
 private final ExternalChangeGovernanceRepository repository; private final ProviderActionCandidateLedger ledger; private final ProviderActionCommandPort commandPort; private final ProviderActionCandidateStateMachine machine=new ProviderActionCandidateStateMachine();
 public ProviderActionCandidateService(ExternalChangeGovernanceRepository repository,ProviderActionCandidateLedger ledger,ProviderActionCommandPort commandPort){this.repository=repository;this.ledger=ledger;this.commandPort=commandPort;}
 @Transactional public ProviderActionCandidate create(String tenantId,String conflictId,String observationId,String connectionId,String projectId,String issueId,ProviderActionCandidateType type,IntegrationRiskLevel risk,String commandJson,String providerIdentityHash,boolean reauth,boolean approval,String idempotencyKey,String correlationId){Optional<ProviderActionCandidate> existing=repository.findCandidateByIdempotency(tenantId,idempotencyKey);if(existing.isPresent())return existing.get();OffsetDateTime now=now();ProviderActionCandidate c=new ProviderActionCandidate(tenantId,"candidate-"+UUID.randomUUID(),conflictId,observationId,connectionId,projectId,issueId,type,risk,ProviderActionCandidateStatus.PENDING_REVIEW,commandJson,sha(commandJson),providerIdentityHash,reauth,approval,"",null,"",null,"",null,"","",idempotencyKey,1,correlationId,now,now);repository.saveCandidate(c);ledger.append(c,ProviderActionCandidateEventType.CANDIDATE_CREATED,"SYSTEM","PROVIDER_ACTION_CANDIDATE_CREATED","{\"type\":\""+type+"\"}");return c;}
 @Transactional public ProviderActionCandidate review(String tenantId,String candidateId,long expectedVersion,String actor,String reason,String reauthEvidence){ProviderActionCandidate c=find(tenantId,candidateId);requireVersion(c,expectedVersion);ProviderActionCandidateStatus next=c.requiresReauthentication()&&(reauthEvidence==null||reauthEvidence.isBlank())?ProviderActionCandidateStatus.WAIT_REAUTHENTICATION:c.requiresApproval()?ProviderActionCandidateStatus.WAIT_APPROVAL:ProviderActionCandidateStatus.APPROVED;machine.requireTransition(c.status(),next);ProviderActionCandidate n=copy(c,next,actor,now(),c.approvedBy(),c.approvedAt(),c.executedBy(),c.executedAt(),c.executionEvidence(),reason,c.version()+1);save(n,c.version());ledger.append(n,next==ProviderActionCandidateStatus.WAIT_REAUTHENTICATION?ProviderActionCandidateEventType.REVIEW_STARTED:ProviderActionCandidateEventType.REAUTHENTICATION_VERIFIED,actor,"CANDIDATE_REVIEWED","{\"nextStatus\":\""+next+"\"}");return n;}
 @Transactional public ProviderActionCandidate approve(String tenantId,String candidateId,long expectedVersion,String actor,String reason,String reauthEvidence){ProviderActionCandidate c=find(tenantId,candidateId);requireVersion(c,expectedVersion);if(c.requiresReauthentication()&&(reauthEvidence==null||reauthEvidence.isBlank()))throw new IllegalArgumentException("REAUTHENTICATION_EVIDENCE_REQUIRED");if(c.requiresApproval()&&!c.reviewedBy().isBlank()&&c.reviewedBy().equals(actor))throw new IllegalArgumentException("SEPARATION_OF_DUTIES_REQUIRED");machine.requireTransition(c.status(),ProviderActionCandidateStatus.APPROVED);ProviderActionCandidate n=copy(c,ProviderActionCandidateStatus.APPROVED,c.reviewedBy(),c.reviewedAt(),actor,now(),c.executedBy(),c.executedAt(),c.executionEvidence(),reason,c.version()+1);save(n,c.version());ledger.append(n,ProviderActionCandidateEventType.APPROVAL_GRANTED,actor,"CANDIDATE_APPROVED","{}");return n;}
 @Transactional public ProviderActionCandidate reject(String tenantId,String candidateId,long expectedVersion,String actor,String reason){ProviderActionCandidate c=find(tenantId,candidateId);requireVersion(c,expectedVersion);machine.requireTransition(c.status(),ProviderActionCandidateStatus.REJECTED);ProviderActionCandidate n=copy(c,ProviderActionCandidateStatus.REJECTED,actor,now(),c.approvedBy(),c.approvedAt(),c.executedBy(),c.executedAt(),c.executionEvidence(),reason,c.version()+1);save(n,c.version());ledger.append(n,ProviderActionCandidateEventType.APPROVAL_REJECTED,actor,"CANDIDATE_REJECTED","{}");return n;}
 @Transactional public ProviderActionCandidate execute(String tenantId,String candidateId,long expectedVersion,String actor,String reason,String reauthEvidence,String idempotencyKey){return execute(tenantId,candidateId,expectedVersion,actor,reason,reauthEvidence,idempotencyKey,null);}
 @Transactional public ProviderActionCandidate execute(String tenantId,String candidateId,long expectedVersion,String actor,String reason,String reauthEvidence,String idempotencyKey,ProviderExecutionAuthorizationRef executionAuthorization){ProviderActionCandidate c=find(tenantId,candidateId);requireVersion(c,expectedVersion);if(c.status()!=ProviderActionCandidateStatus.APPROVED&&c.status()!=ProviderActionCandidateStatus.EXECUTION_FAILED)throw new IllegalStateException("CANDIDATE_NOT_EXECUTABLE");if(c.requiresReauthentication()&&(reauthEvidence==null||reauthEvidence.isBlank()))throw new IllegalArgumentException("REAUTHENTICATION_EVIDENCE_REQUIRED");ProviderActionCandidate pending=copy(c,ProviderActionCandidateStatus.EXECUTION_PENDING,c.reviewedBy(),c.reviewedAt(),c.approvedBy(),c.approvedAt(),actor,null,"",reason,c.version()+1);save(pending,c.version());ledger.append(pending,ProviderActionCandidateEventType.EXECUTION_REQUESTED,actor,"CONTROLLED_COMMAND_REQUESTED","{}");ProviderActionCandidate running=copy(pending,ProviderActionCandidateStatus.EXECUTING,pending.reviewedBy(),pending.reviewedAt(),pending.approvedBy(),pending.approvedAt(),actor,null,"",reason,pending.version()+1);save(running,pending.version());ledger.append(running,ProviderActionCandidateEventType.EXECUTION_STARTED,actor,"CONTROLLED_COMMAND_STARTED","{}");ProviderActionCommandResult result=commandPort.execute(new ProviderActionCommand(tenantId,candidateId,c.candidateType(),c.requestedCommandJson(),running.version(),idempotencyKey,actor,reason,reauthEvidence,c.correlationId(),executionAuthorization));ProviderActionCandidateStatus finalStatus=result.accepted()?ProviderActionCandidateStatus.EXECUTED:ProviderActionCandidateStatus.EXECUTION_FAILED;ProviderActionCandidate done=copy(running,finalStatus,running.reviewedBy(),running.reviewedAt(),running.approvedBy(),running.approvedAt(),actor,now(),result.evidenceReference(),reason,running.version()+1);save(done,running.version());ledger.append(done,result.accepted()?ProviderActionCandidateEventType.EXECUTION_SUCCEEDED:ProviderActionCandidateEventType.EXECUTION_FAILED,actor,result.reasonCode(),"{\"retryable\":"+result.retryable()+"}");return done;}
 public ProviderActionCandidate find(String tenantId,String id){return repository.findCandidate(tenantId,id).orElseThrow(()->new IllegalArgumentException("PROVIDER_ACTION_CANDIDATE_NOT_FOUND"));} public List<ProviderActionCandidate> list(String tenantId,ProviderActionCandidateStatus status,int limit){return repository.listCandidates(tenantId,status,Math.max(1,Math.min(limit,1000)));} public List<ProviderActionCandidateEvent> events(String tenantId,String id,int limit){return repository.listCandidateEvents(tenantId,id,Math.max(1,Math.min(limit,1000)));}
 private void save(ProviderActionCandidate n,long expected){if(!repository.saveCandidateExpectedVersion(n,expected))throw new IllegalStateException("CANDIDATE_EXPECTED_VERSION_MISMATCH");} private void requireVersion(ProviderActionCandidate c,long v){if(c.version()!=v)throw new IllegalStateException("CANDIDATE_EXPECTED_VERSION_MISMATCH");}
 private ProviderActionCandidate copy(ProviderActionCandidate c,ProviderActionCandidateStatus s,String reviewedBy,OffsetDateTime reviewedAt,String approvedBy,OffsetDateTime approvedAt,String executedBy,OffsetDateTime executedAt,String evidence,String reason,long version){return new ProviderActionCandidate(c.tenantId(),c.candidateId(),c.conflictId(),c.observationId(),c.connectionId(),c.externalProjectId(),c.externalIssueId(),c.candidateType(),c.riskLevel(),s,c.requestedCommandJson(),c.requestHash(),c.providerIdentityHash(),c.requiresReauthentication(),c.requiresApproval(),reviewedBy,reviewedAt,approvedBy,approvedAt,executedBy,executedAt,evidence,reason,c.idempotencyKey(),version,c.correlationId(),c.createdAt(),now());}
 private String sha(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}} private OffsetDateTime now(){return OffsetDateTime.now(ZoneOffset.UTC);}
}
